import {loadAmazonSpApiCredentials} from '../_shared/amazon/config.ts';
import { createClient } from 'npm:@supabase/supabase-js@2';
import { verifyShopifyInstallLaunch, shopifyDomain, shopifyError, shopifyHash, verifyShopifyCallback, shopifyTokenRequest, shopifyTokenCredentials, shopifyAccountCredentials, shopifyLegacyCredentials, commitShopifyAuthorization, shopifyStoredApplicationCredentials } from '../_shared/shopifyAuth.ts';
import { enforceWorkspaceLimit, requireWorkspaceEntitlement } from '../_shared/saas/entitlements.ts';
import { gmailAccessAllowed, gmailServerConfig, validateGmailOrigin, gmailTokenRequest, gmailProfileEmail, gmailConnectionFromToken, legacyGmailMigrationPlan } from '../_shared/gmailOAuth.ts';

const corsHeaders={
  'Access-Control-Allow-Origin':'*',
  'Access-Control-Allow-Headers':'authorization, x-client-info, apikey, content-type, x-requested-with',
  'Access-Control-Allow-Methods':'POST, OPTIONS',
};
const headers={...corsHeaders,'Content-Type':'application/json'};
const PROVIDERS=new Set(['amazon','sendcloud','envia','mrw','shopify','gmail']);
const SENDCLOUD_BASE='https://panel.sendcloud.sc/api/v3';
const SP_API_BASE='https://sellingpartnerapi-eu.amazon.com';

type Caller={user_id:string;data_owner_id:string;role:string;active:boolean;permissions:string[]|null};
type Provider='amazon'|'sendcloud'|'envia'|'mrw'|'shopify'|'gmail';

function response(data:unknown,status=200){return new Response(JSON.stringify(data),{status,headers});}
function clean(v:unknown){return String(v??'').trim();}
function getAdminKey(){
  const secretKeys=Deno.env.get('SUPABASE_SECRET_KEYS');
  if(secretKeys){try{const parsed=JSON.parse(secretKeys);if(typeof parsed?.default==='string'&&parsed.default.trim())return parsed.default.trim()}catch{/* fallback */}}
  return clean(Deno.env.get('SUPABASE_SERVICE_ROLE_KEY'));
}
function sanitize(value:unknown){
  return shopifyError(value,'Error interno.')
    .replace(/Atz[ar]\|[A-Za-z0-9._|\-]+/g,'[redacted-token]')
    .replace(/("(?:client_secret|refresh_token|access_token|secretKey|secret_key|token|apiToken)"\s*:\s*")([^"]+)(")/gi,'$1[redacted]$3')
    .slice(0,700);
}
async function authenticate(req:Request,admin:any,action:string):Promise<Caller>{
  const token=clean(req.headers.get('Authorization')).replace(/^Bearer\s+/i,'');
  if(!token)throw new Error('Sesión no válida.');
  const {data:userData,error:userError}=await admin.auth.getUser(token);
  if(userError||!userData?.user)throw new Error('Sesión no válida.');
  const {data:caller,error}=await admin.from('app_users')
    .select('user_id,data_owner_id,role,active,permissions')
    .eq('user_id',userData.user.id).maybeSingle();
  if(error)throw error;
  if(!caller?.active)throw new Error('Tu acceso está desactivado.');
  const {data:workspace,error:workspaceError}=await admin.from('workspaces').select('status').eq('id',caller.data_owner_id).maybeSingle();
  if(workspaceError)throw workspaceError;
  if(!workspace||!['active','trialing'].includes(workspace.status))throw new Error('El acceso de tu empresa está suspendido.');
  if(!gmailAccessAllowed(caller,action))throw new Error('Solo un administrador puede gestionar integraciones; consultar Gmail requiere permiso de Gastos.');
  return caller as Caller;
}
function publicAccount(row:any){
  return {
    id:row.id,
    provider:row.provider,
    displayName:row.display_name,
    externalAccountId:row.external_account_id,
    status:row.status,
    enabled:Boolean(row.enabled),
    isDefault:Boolean(row.is_default),
    credentialSource:row.credential_source,
    credentialsConfigured:Boolean(row.secret_id)||['environment','session','derived'].includes(row.credential_source),
    parentAccountId:row.parent_account_id,
    linkedResourceId:row.linked_resource_id,
    config:row.config||{},
    lastTestedAt:row.last_tested_at,
    lastSuccessAt:row.last_success_at,
    lastError:row.last_error,
    createdAt:row.created_at,
    updatedAt:row.updated_at,
  };
}
async function listAccounts(admin:any,ownerId:string){
  const {data,error}=await admin.from('integration_accounts')
    .select('*').eq('owner_id',ownerId).order('provider').order('is_default',{ascending:false}).order('display_name');
  if(error)throw error;
  return (data||[]).filter((account:any)=>
    !account.config?.archivedAt &&
    !(account.provider==='gmail'&&account.config?.migratedToAccountId)
  ).map(publicAccount);
}

async function consolidateLegacyGmail(admin:any,ownerId:string,target:any){
  const rows=await admin.from('integration_accounts').select('*').eq('owner_id',ownerId).eq('provider','gmail');
  if(rows.error)throw rows.error;
  const plan=legacyGmailMigrationPlan(rows.data||[],target);
  for(const id of plan.ids){
    const history=await admin.from('gmail_imports').update({integration_account_id:target.id}).eq('owner_id',ownerId).eq('integration_account_id',id);
    if(history.error)throw history.error;
    const old=rows.data.find((account:any)=>account.id===id);
    const archived=await admin.from('integration_accounts').update({enabled:false,status:'disabled',is_default:false,config:{...old.config,migratedToAccountId:target.id},updated_at:new Date().toISOString()}).eq('owner_id',ownerId).eq('id',id);
    if(archived.error)throw archived.error;
  }
  if(plan.transferDefault)await makeDefault(admin,ownerId,'gmail',target.id);
  return loadAccount(admin,ownerId,target.id);
}
async function readVault(admin:any,secretId:string|null){
  if(!secretId)return {};
  const {data,error}=await admin.rpc('integration_read_secret',{p_secret_id:secretId});
  if(error)throw error;
  try{return JSON.parse(String(data||'{}'))}catch{throw new Error('Las credenciales almacenadas no tienen un formato válido.')}
}
async function writeVault(admin:any,accountId:string,provider:Provider,credentials:Record<string,unknown>,existingId:string|null){
  const payload=JSON.stringify(credentials);
  if(provider==='shopify'){
    const {data,error}=await admin.rpc('integration_shopify_replace_secret',{p_account_id:accountId,p_secret:payload});
    if(error)throw error;
    return String(data);
  }
  const {data,error}=await admin.rpc('integration_store_secret',{
    p_secret:payload,
    p_name:`integration:${provider}:${accountId}`,
    p_description:`Credenciales cifradas para ${provider} (${accountId})`,
    p_existing_secret_id:existingId,
  });
  if(error)throw error;
  return String(data);
}

async function renewGmail(admin:any,account:any,forceRefresh=false){
  const config=gmailServerConfig();
  if(!config.persistent)throw new Error('La conexión persistente de Google no está habilitada. Contacta con el administrador de Zenvia.');
  const stored=await readVault(admin,account.secret_id);
  if(!stored.refreshToken)throw new Error('Renueva la autorización de esta cuenta desde Integraciones.');
  if(stored.clientId!==config.clientId)throw new Error('La configuración de Google ha cambiado. Renueva la cuenta en Integraciones.');
  if(!forceRefresh&&stored.accessToken&&Number(stored.expiresAt)>Date.now()+300000)return {email:account.external_account_id,accessToken:stored.accessToken,expiresAt:stored.expiresAt};
  const token=await gmailTokenRequest(new URLSearchParams({grant_type:'refresh_token',client_id:config.clientId,client_secret:config.clientSecret,refresh_token:stored.refreshToken}));
  const connection=gmailConnectionFromToken(token,account.external_account_id);
  await writeVault(admin,account.id,'gmail',{...stored,...connection,...(token.refresh_token?{refreshToken:token.refresh_token}:{})},account.secret_id);
  return connection;
}
async function loadAccount(admin:any,ownerId:string,id:string){
  const {data,error}=await admin.from('integration_accounts').select('*').eq('owner_id',ownerId).eq('id',id).maybeSingle();
  if(error)throw error;
  if(!data||data.config?.archivedAt)throw new Error('Integración no encontrada.');
  return data;
}
async function makeDefault(admin:any,ownerId:string,provider:Provider,id:string){
  const clear=await admin.from('integration_accounts').update({is_default:false,updated_at:new Date().toISOString()}).eq('owner_id',ownerId).eq('provider',provider).neq('id',id);
  if(clear.error)throw clear.error;
  const set=await admin.from('integration_accounts').update({is_default:true,updated_at:new Date().toISOString()}).eq('owner_id',ownerId).eq('id',id);
  if(set.error)throw set.error;
}
async function amazonCredentials(admin:any,account:any){
  return loadAmazonSpApiCredentials(admin,{integrationAccountId:account.id,ownerId:account.owner_id});
}
async function amazonToken(c:any){
  const body=new URLSearchParams();
  body.set('grant_type','refresh_token');
  body.set('refresh_token',c.refreshToken);
  body.set('client_id',c.clientId);
  body.set('client_secret',c.clientSecret);
  const res=await fetch('https://api.amazon.com/auth/o2/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});
  const text=await res.text();let data:any={};try{data=JSON.parse(text)}catch{}
  if(!res.ok||!data?.access_token)throw new Error(`Amazon LWA (${res.status}): ${sanitize(data?.error_description||data?.error||text)}`);
  return String(data.access_token);
}
async function amazonParticipations(admin:any,ownerId:string,account:any){
  const credentials=await amazonCredentials(admin,account);
  const token=await amazonToken(credentials);
  const res=await fetch(`${SP_API_BASE}/sellers/v1/marketplaceParticipations`,{headers:{
    Accept:'application/json',
    'user-agent':'ZENVIA-Gestion/1.0 (Integration Manager)',
    'x-amz-access-token':token,
    'x-amz-date':new Date().toISOString().replace(/[:-]|\.\d{3}/g,''),
  }});
  const text=await res.text();let data:any={};try{data=JSON.parse(text)}catch{}
  if(!res.ok)throw new Error(`Amazon SP-API (${res.status}): ${sanitize(data?.errors?.[0]?.message||data?.message||text)}`);
  const rows=(data?.payload||[]).filter((x:any)=>x?.marketplace?.id&&x?.marketplace?.countryCode);
  const now=new Date().toISOString();
  let amazonAccountId=account.linked_resource_id as string|null;
  if(!amazonAccountId){
    const upsert=await admin.from('amazon_accounts').upsert({
      owner_id:ownerId,seller_id:credentials.sellerId,display_name:account.display_name||'Amazon',
      region:'EU',status:'connected',integration_account_id:account.id,updated_at:now,
    },{onConflict:'owner_id,seller_id'}).select('id').single();
    if(upsert.error)throw upsert.error;
    amazonAccountId=upsert.data.id;
    const link=await admin.from('integration_accounts').update({linked_resource_id:amazonAccountId}).eq('id',account.id).eq('owner_id',ownerId);
    if(link.error)throw link.error;
  }else{
    const update=await admin.from('amazon_accounts').update({status:'connected',display_name:account.display_name,updated_at:now,integration_account_id:account.id})
      .eq('id',amazonAccountId).eq('owner_id',ownerId);
    if(update.error)throw update.error;
  }
  const inactive=await admin.from('amazon_marketplaces').update({active:false,updated_at:now}).eq('owner_id',ownerId).eq('amazon_account_id',amazonAccountId);
  if(inactive.error)throw inactive.error;
  const markets=rows.map((item:any)=>({
    owner_id:ownerId,amazon_account_id:amazonAccountId,marketplace_id:String(item.marketplace.id),
    country_code:String(item.marketplace.countryCode||'').toUpperCase(),
    name:String(item.marketplace.name||item.marketplace.countryCode||item.marketplace.id),
    currency_code:String(item.marketplace.defaultCurrencyCode||'EUR').toUpperCase(),
    active:Boolean(item.participation?.isParticipating),updated_at:now,
  }));
  if(markets.length){
    const upsert=await admin.from('amazon_marketplaces').upsert(markets,{onConflict:'owner_id,amazon_account_id,marketplace_id'});
    if(upsert.error)throw upsert.error;
  }
  return {amazonAccountId,marketplaces:markets.filter((x:any)=>x.active)};
}
async function sendcloudCredentials(admin:any,account:any){
  const stored=account.secret_id?await readVault(admin,account.secret_id):{};
  let publicKey=clean((stored as any).publicKey||(stored as any).public_key);
  let secretKey=clean((stored as any).secretKey||(stored as any).secret_key);
  if(account.credential_source==='environment'){
    publicKey=publicKey||clean(Deno.env.get('SENDCLOUD_PUBLIC_KEY')||Deno.env.get('SENDCLOUD_API_KEY'));
    secretKey=secretKey||clean(Deno.env.get('SENDCLOUD_SECRET_KEY')||Deno.env.get('SENDCLOUD_API_SECRET'));
  }
  if(!publicKey||!secretKey)throw new Error('Faltan las claves Public y Secret de Sendcloud.');
  return {publicKey,secretKey};
}
async function enviaCredentials(admin:any,account:any){
  const stored=account.secret_id?await readVault(admin,account.secret_id):{};
  const token=clean((stored as any).token||(stored as any).apiToken||(stored as any).api_token);
  if(!token)throw new Error('Falta el token API de Envia.com.');
  const environment=account.config?.environment==='production'?'production':'sandbox';
  return {token,environment};
}
async function mrwCredentials(admin:any,account:any){
  const stored=account.secret_id?await readVault(admin,account.secret_id):{};
  const credentials={
    franchiseCode:clean((stored as any).franchiseCode||(stored as any).codigoFranquicia),
    subscriberCode:clean((stored as any).subscriberCode||(stored as any).codigoAbonado),
    departmentCode:clean((stored as any).departmentCode||(stored as any).codigoDepartamento),
    username:clean((stored as any).username||(stored as any).userName||(stored as any).usuario),
    password:clean((stored as any).password),
  };
  if(!credentials.franchiseCode||!credentials.subscriberCode||!credentials.username||!credentials.password)throw new Error('Faltan credenciales MRW: franquicia, abonado, usuario o contraseña.');
  return credentials;
}
function mrwEsc(value:unknown){return clean(value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;')}
function mrwResponseError(text:string,status:number){
  const fault=(text.match(/<faultstring[^>]*>([\s\S]*?)<\/faultstring>/i)?.[1]
    ||text.match(/<Mensaje[^>]*>([\s\S]*?)<\/Mensaje>/i)?.[1]
    ||text.match(/<DescripcionError[^>]*>([\s\S]*?)<\/DescripcionError>/i)?.[1]
    ||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  if(fault)return `MRW: ${sanitize(fault)}`;
  if(/<!doctype html|<html[\s>]/i.test(text)){
    return `MRW (${status}) devolvió un error interno al validar la conexión. Las credenciales se han guardado, pero MRW no ha podido verificarlas todavía.`;
  }
  return `MRW (${status}): ${sanitize(text||'respuesta no válida')}`;
}
async function mrwGatewayRequest(payload:Record<string,unknown>){
  const url=clean(Deno.env.get('MRW_GATEWAY_URL')),secret=clean(Deno.env.get('MRW_GATEWAY_SECRET'));
  if(!url||!secret)return null;
  const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-Zenvia-Gateway-Key':secret},body:JSON.stringify(payload)});
  const data=await res.json().catch(()=>({}));
  if(!res.ok)throw new Error(`MRW gateway HTTP ${res.status}: ${sanitize((data as any)?.error||'respuesta no válida')}`);
  const upstreamStatus=Number((data as any)?.status||0);
  const contentType=clean((data as any)?.contentType);
  const bodyBase64=clean((data as any)?.bodyBase64);
  const body=bodyBase64?atob(bodyBase64):'';
  return {status:upstreamStatus,contentType,body};
}
async function testMrw(admin:any,ownerId:string,account:any){
  const creds=await mrwCredentials(admin,account);
  const environment=account.config?.environment==='test'?'test':'production';
  const base=environment==='test'?'https://sagec-test.mrw.es/MRWEnvio.asmx':'https://sagec.mrw.es/MRWEnvio.asmx';
  const auth=`<AuthInfo xmlns="http://www.mrw.es/"><CodigoFranquicia>${mrwEsc(creds.franchiseCode)}</CodigoFranquicia><CodigoAbonado>${mrwEsc(creds.subscriberCode)}</CodigoAbonado><CodigoDepartamento>${mrwEsc(creds.departmentCode)}</CodigoDepartamento><UserName>${mrwEsc(creds.username)}</UserName><Password>${mrwEsc(creds.password)}</Password></AuthInfo>`;

  // Use MRW's read-only GetPointsDB contract with a real destination postcode.
  // This verifies authentication without creating/cancelling shipments or requesting
  // labels for numbers that MRW may not consider native to this SAGEC account.
  const {data:recentOrders}=await admin.from('fulfillment_orders')
    .select('shipping_address,updated_at')
    .eq('owner_id',ownerId)
    .order('updated_at',{ascending:false})
    .limit(100);
  const postal=(recentOrders||[])
    .map((row:any)=>clean(row?.shipping_address?.postal_code).replace(/\s+/g,''))
    .find((value:string)=>/^\d{5}$/.test(value))||'28001';

  // MRW currently returns HTTP 500 for ?WSDL from public clients, while its
  // operation pages remain available. Do not use WSDL availability as a network test.
  const gatewayOperation=await mrwGatewayRequest({environment,method:'GET',resource:'operation'});
  let operationStatus:number,operationText:string;
  if(gatewayOperation){operationStatus=gatewayOperation.status;operationText=gatewayOperation.body}
  else{
    const operation=await fetch(base+'?op=GetPointsDB',{headers:{Accept:'text/html,application/xhtml+xml','User-Agent':'ZENVIA-Gestion/1.0'}});
    operationStatus=operation.status;operationText=await operation.text();
  }
  if(operationStatus<200||operationStatus>=300||!/GetPointsDB/i.test(operationText)){
    throw new Error(`MRW SAGEC no expone la página de operación GetPointsDB desde ${gatewayOperation?'el gateway Vercel':'nuestro servidor'} (HTTP ${operationStatus}).`);
  }
  const request=`<request><Point><codigoPoint></codigoPoint><CodigoPostal>${mrwEsc(postal)}</CodigoPostal></Point></request>`;
  const envelope=`<?xml version="1.0" encoding="utf-8"?><soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Header>${auth}</soap:Header><soap:Body><GetPointsDB xmlns="http://www.mrw.es/">${request}</GetPointsDB></soap:Body></soap:Envelope>`;
  const gatewaySoap=await mrwGatewayRequest({environment,method:'POST',operation:'GetPointsDB',soapVersion:'1.1',body:envelope});
  const directRes=gatewaySoap?null:await fetch(base,{method:'POST',headers:{'Content-Type':'text/xml; charset=utf-8','SOAPAction':'"http://www.mrw.es/GetPointsDB"',Accept:'text/xml','User-Agent':'ZENVIA-Gestion/1.0'},body:envelope});
  const status=gatewaySoap?gatewaySoap.status:directRes!.status;
  const responseContentType=gatewaySoap?gatewaySoap.contentType:(directRes!.headers.get('content-type')||'');
  const raw=gatewaySoap?gatewaySoap.body:await directRes!.text();
  const fault=(raw.match(/<faultstring[^>]*>([\s\S]*?)<\/faultstring>/i)?.[1]
    ||raw.match(/<Mensaje[^>]*>([\s\S]*?)<\/Mensaje>/i)?.[1]
    ||raw.match(/<DescripcionError[^>]*>([\s\S]*?)<\/DescripcionError>/i)?.[1]
    ||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  const title=(raw.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  const bodyText=raw.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/\s+/g,' ').trim();

  if(status>=200&&status<300&&/GetPointsDBResponse/i.test(raw)){
    return {environment,apiMode:'modern',validationOperation:'GetPointsDB',soap:'1.1',postalCode:postal};
  }
  if(fault){
    if(/usuario|password|contrase|abonado|franquicia|autent|credencial|acceso|login|unauthorized|no autorizado/i.test(fault)){
      throw new Error(`MRW ha rechazado las credenciales: ${sanitize(fault)}`);
    }
    // A business SOAP fault means MRW authenticated and parsed the request.
    return {environment,apiMode:'modern',validationOperation:'GetPointsDB-fault',soap:'1.1',detail:sanitize(fault),postalCode:postal};
  }
  const htmlDetail=sanitize(title||bodyText||'sin detalle');
  throw new Error(`El WSDL de MRW SAGEC es accesible desde ${gatewaySoap?'el gateway de IP fija':'ZENVIA'}, pero la llamada SOAP autenticada devuelve HTTP ${status} (${responseContentType||'sin content-type'}): ${htmlDetail}.`);
}
async function enviaCarriers(admin:any,account:any){
  const c=await enviaCredentials(admin,account);
  const base=c.environment==='production'?'https://queries.envia.com':'https://queries.test.envia.com';
  const res=await fetch(`${base}/carrier?country_code=ES`,{headers:{Authorization:`Bearer ${c.token}`,Accept:'application/json'}});
  const text=await res.text();let data:any={};try{data=JSON.parse(text)}catch{}
  if(!res.ok)throw new Error(`Envia.com (${res.status}): ${sanitize(data?.message||data?.error||text)}`);
  const rows=Array.isArray(data?.data)?data.data:Array.isArray(data)?data:[];
  return rows;
}
async function sendcloudIntegrations(admin:any,account:any){
  const c=await sendcloudCredentials(admin,account);
  const auth=`Basic ${btoa(`${c.publicKey}:${c.secretKey}`)}`;
  const res=await fetch(`${SENDCLOUD_BASE}/integrations`,{headers:{Authorization:auth,Accept:'application/json'}});
  const text=await res.text();let data:any={};try{data=JSON.parse(text)}catch{}
  if(!res.ok)throw new Error(`Sendcloud (${res.status}): ${sanitize(data?.message||data?.error||text)}`);
  return (data?.data||[]).map((item:any)=>{
    const value=`${item?.type||''} ${item?.shop_name||''} ${item?.shop_url||''}`.toLowerCase();
    return {
      id:Number(item.id),shopName:String(item.shop_name||item.type||`Integración ${item.id}`),
      type:String(item.type||''),shopUrl:item.shop_url||null,
      channel:value.includes('shopify')?'shopify':value.includes('amazon')?'amazon':'other',
    };
  });
}
function normalizeShopifyDomain(value:unknown){
  return shopifyDomain(value);
}
async function shopifyCredentials(admin:any,account:any){
  return shopifyAccountCredentials(admin,account,await shopifyOAuthConfig(admin,account.owner_id));
}

async function shopifyOAuthConfig(admin:any,ownerId:string){
  const credentials=await shopifyStoredApplicationCredentials(admin,ownerId);
  const allowedOrigins=(Deno.env.get('SHOPIFY_ALLOWED_ORIGINS')||'https://gestion.zenviacommerce.com,https://gestionzenvia.vercel.app').split(',').map(value=>value.trim()).filter(Boolean);
  return {...credentials,allowedOrigins};
}

async function saveShopifyConnection(admin:any,ownerId:string,body:any,stored:any){
  const domain=shopifyDomain(stored.shopDomain);
  const existing=await admin.from('integration_accounts').select('*').eq('owner_id',ownerId).eq('provider','shopify').eq('external_account_id',domain).maybeSingle();
  if(existing.error)throw existing.error;
  let account=existing.data;
  if(body.accountId){
    const requested=await loadAccount(admin,ownerId,clean(body.accountId));
    if(requested.provider!=='shopify')throw new Error('La cuenta seleccionada no corresponde a Shopify.');
    if(account&&account.id!==requested.id)throw new Error('Esta tienda ya está conectada en otra cuenta.');
    account=requested;
  }
  if(!account){
    const inserted=await admin.from('integration_accounts').insert({owner_id:ownerId,provider:'shopify',display_name:clean(body.displayName)||domain.replace('.myshopify.com',''),external_account_id:domain,credential_source:'vault',status:'pending',config:{shopDomain:domain,syncOrders:body.syncOrders!==false,apiVersion:'2026-07'}}).select('*').single();
    if(inserted.error)throw inserted.error;account=inserted.data;
  }
  const secretId=await writeVault(admin,account.id,'shopify',stored,account.secret_id);
  const restoredConfig={...account.config};delete restoredConfig.archivedAt;delete restoredConfig.oauthStateHash;
  const saved=await admin.from('integration_accounts').update({secret_id:secretId,external_account_id:domain,credential_source:'vault',parent_account_id:null,enabled:true,status:'connected',display_name:clean(body.displayName)||account.display_name,last_error:null,config:{...restoredConfig,shopDomain:domain,authMode:stored.authMode,syncOrders:body.syncOrders!==false,apiVersion:'2026-07'}}).eq('id',account.id).eq('owner_id',ownerId).select('*').single();
  if(saved.error)throw saved.error;
  const defaults=await admin.from('integration_accounts').select('id').eq('owner_id',ownerId).eq('provider','shopify').eq('is_default',true).neq('status','disabled');
  if(defaults.error)throw defaults.error;
  if(!defaults.data?.length)await makeDefault(admin,ownerId,'shopify',account.id);
  return saved.data;
}
async function shopifyGraphql(admin:any,account:any,query:string,variables:Record<string,unknown>={}){
  const credentials=await shopifyCredentials(admin,account);
  const res=await fetch(`https://${credentials.shopDomain}/admin/api/${credentials.apiVersion}/graphql.json`,{
    method:'POST',
    headers:{'Content-Type':'application/json','Accept':'application/json','X-Shopify-Access-Token':credentials.accessToken},
    body:JSON.stringify({query,variables}),
  });
  const text=await res.text();let data:any={};try{data=JSON.parse(text)}catch{}
  if(!res.ok)throw new Error(`Shopify (${res.status}): ${sanitize(data?.errors?.[0]?.message||text)}`);
  if(Array.isArray(data?.errors)&&data.errors.length)throw new Error(`Shopify: ${sanitize(data.errors.map((item:any)=>item?.message).filter(Boolean).join(' · '))}`);
  return {data,credentials};
}
async function testAccount(admin:any,ownerId:string,account:any){
  const now=new Date().toISOString();
  try{
    let detail:any={};
    if(account.provider==='amazon'){
      const result=await amazonParticipations(admin,ownerId,account);
      detail={marketplaces:result.marketplaces.length};
    }else if(account.provider==='sendcloud'){
      const integrations=await sendcloudIntegrations(admin,account);
      detail={integrations:integrations.length};
    }else if(account.provider==='envia'){
      const carriers=await enviaCarriers(admin,account);
      detail={carriers:carriers.length,environment:account.config?.environment==='production'?'production':'sandbox'};
    }else if(account.provider==='mrw'){
      detail=await testMrw(admin,ownerId,account);
    }else if(account.provider==='shopify'){
      const result=await shopifyGraphql(admin,account,'query ZenviaShopIdentity { shop { id name myshopifyDomain } }');
      const shop=result.data?.data?.shop;
      if(!shop?.id)throw new Error('Shopify no devolvió la identidad de la tienda.');
      detail={shopName:shop.name,shopUrl:shop.myshopifyDomain,apiVersion:result.credentials.apiVersion};
    }else if(account.provider==='gmail'){
      if(account.credential_source==='vault'){
        const connection=await renewGmail(admin,account);
        if(await gmailProfileEmail(connection.accessToken)!==account.external_account_id.toLowerCase())throw new Error('La autorización no corresponde al buzón guardado.');
      }
      detail={requiresBrowserSession:account.credential_source!=='vault'};
    }
    const nextConfig=account.provider==='mrw'&&detail?.apiMode?{...(account.config||{}),apiMode:detail.apiMode,soapVersion:detail.soap||null}:account.config;
    const update=await admin.from('integration_accounts').update({
      status:'connected',last_tested_at:now,last_success_at:now,last_error:null,updated_at:now,config:nextConfig,
    }).eq('id',account.id).eq('owner_id',ownerId).eq('enabled',true).neq('status','disabled');
    if(update.error)throw update.error;
    return {ok:true,checkedAt:now,detail};
  }catch(error){
    const message=sanitize(error instanceof Error?error.message:error);
    await admin.from('integration_accounts').update({status:'error',last_tested_at:now,last_error:message,updated_at:now})
      .eq('id',account.id).eq('owner_id',ownerId);
    throw new Error(message||'No se pudo comprobar la integración.');
  }
}

Deno.serve(async(req:Request)=>{
  if(req.method==='OPTIONS')return new Response('ok',{headers:corsHeaders});
  if(req.method!=='POST')return response({error:'Método no permitido.'},405);
  const url=clean(Deno.env.get('SUPABASE_URL')),key=getAdminKey();
  if(!url||!key)return response({error:'Configuración interna de Supabase no disponible.'},500);
  const admin=createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
  try{
    const body=await req.json().catch(()=>({}));
    const action=clean(body?.action||'list');
    const caller=await authenticate(req,admin,action);
    if(['shopify_client_connect','shopify_install_connect','shopify_oauth_start','shopify_oauth_exchange'].includes(action)){
      await requireWorkspaceEntitlement(admin,caller.data_owner_id,'integration.shopify','Tu plan no incluye la integración con Shopify.');
    }

    if(action==='shopify_config'){
      const config=await shopifyOAuthConfig(admin,caller.data_owner_id);
      return response({ready:config.ready,redirectUri:config.allowedOrigins[0]+'/'});
    }
    if(action==='shopify_app_setup'){
      const clientId=clean(body.clientId),clientSecret=clean(body.clientSecret);
      if(clientId.length<16||clientSecret.length<16)throw new Error('Introduce el ID y el secreto de la app Zenvia desde Shopify Dev Dashboard.');
      const {error}=await admin.rpc('integration_store_secret',{p_secret:JSON.stringify({clientId,clientSecret}),p_name:`shopify-app:${caller.data_owner_id}`,p_description:'Configuración cifrada de la app Shopify de Zenvia',p_existing_secret_id:null});
      if(error)throw error;
      return response({ready:true});
    }
    if(action==='shopify_client_connect'){
      const domain=shopifyDomain(body.shopDomain);
      const clientId=clean(body.clientId),clientSecret=clean(body.clientSecret);
      if(!clientId||!clientSecret)throw new Error('Indica el ID y el secreto de la app instalada en Shopify.');
      const stored=shopifyTokenCredentials({shopDomain:domain,authMode:'client_credentials',clientId,clientSecret},await shopifyTokenRequest(domain,new URLSearchParams({grant_type:'client_credentials',client_id:clientId,client_secret:clientSecret})));
      const account=await saveShopifyConnection(admin,caller.data_owner_id,body,stored);
      await testAccount(admin,caller.data_owner_id,account);
      return response({account:publicAccount(await loadAccount(admin,caller.data_owner_id,account.id))});
    }

    if(action==='shopify_install_connect'){
      const config=await shopifyOAuthConfig(admin,caller.data_owner_id);
      if(!config.ready)throw new Error('Configura la app Shopify de Zenvia antes de conectar la tienda.');
      const params=new URLSearchParams(clean(body.query).replace(/^\?/,''));
      const domain=await verifyShopifyInstallLaunch(params,config.clientSecret);
      const previous=await admin.from('integration_accounts').select('*').eq('owner_id',caller.data_owner_id).eq('provider','shopify').eq('external_account_id',domain).maybeSingle();
      if(previous.error)throw previous.error;
      if(previous.data&&(!previous.data.enabled||previous.data.status==='disabled'))throw new Error('La tienda está desconectada. Actívala desde Integraciones antes de abrir la app.');
      if(previous.data?.status==='connected'){
        await testAccount(admin,caller.data_owner_id,previous.data);
        return response({account:publicAccount(await loadAccount(admin,caller.data_owner_id,previous.data.id))});
      }
      const token=await shopifyTokenRequest(domain,new URLSearchParams({grant_type:'client_credentials',client_id:config.clientId,client_secret:config.clientSecret}));
      const stored=shopifyTokenCredentials({shopDomain:domain,authMode:'client_credentials',clientId:config.clientId,clientSecret:config.clientSecret},token);
      const account=await saveShopifyConnection(admin,caller.data_owner_id,{accountId:previous.data?.id,displayName:previous.data?.display_name,syncOrders:previous.data?.config?.syncOrders!==false},stored);
      await testAccount(admin,caller.data_owner_id,account);
      return response({account:publicAccount(await loadAccount(admin,caller.data_owner_id,account.id))});
    }

    if(action==='shopify_oauth_start'){
      const config=await shopifyOAuthConfig(admin,caller.data_owner_id);
      if(!config.ready)throw new Error('La app común de Shopify todavía no está configurada. Conecta tu app propia con su ID y secreto.');
      const origin=clean(req.headers.get('Origin'));
      if(!config.allowedOrigins.includes(origin))throw new Error('El origen de la autorización no está permitido.');
      const domain=shopifyDomain(body.shopDomain);
      const bytes=crypto.getRandomValues(new Uint8Array(32));
      const state=Array.from(bytes).map(v=>v.toString(16).padStart(2,'0')).join('');
      const stateHash=await shopifyHash(state);
      const pending={shopDomain:domain,authMode:'oauth',clientId:config.clientId,oauthPending:{stateHash,userId:caller.user_id,expiresAt:Date.now()+600000,displayName:clean(body.displayName),syncOrders:body.syncOrders!==false}};
      const existing=await admin.from('integration_accounts').select('*').eq('owner_id',caller.data_owner_id).eq('provider','shopify').eq('external_account_id',domain).maybeSingle();
      if(existing.error)throw existing.error;
      let account=existing.data;
      if(!account){
        const created=await admin.from('integration_accounts').insert({owner_id:caller.data_owner_id,provider:'shopify',display_name:clean(body.displayName)||domain,external_account_id:domain,credential_source:'vault',status:'pending',config:{shopDomain:domain,syncOrders:body.syncOrders!==false}}).select('*').single();
        if(created.error)throw created.error;account=created.data;
      }
      const current=await readVault(admin,account.secret_id);
      const secretId=await writeVault(admin,account.id,'shopify',{...current,oauthPending:pending.oauthPending},account.secret_id);
      const restoredConfig={...account.config,oauthStateHash:stateHash};
      delete restoredConfig.archivedAt;
      const saved=await admin.from('integration_accounts').update({secret_id:secretId,enabled:true,status:account.status==='disabled'?'pending':account.status,config:restoredConfig}).eq('id',account.id).eq('owner_id',caller.data_owner_id);
      if(saved.error)throw saved.error;
      const auth=new URL(`https://${domain}/admin/oauth/authorize`);
      auth.search=new URLSearchParams({client_id:config.clientId,scope:'read_orders,write_orders,read_products,read_inventory,read_merchant_managed_fulfillment_orders,write_merchant_managed_fulfillment_orders',redirect_uri:origin+'/',state}).toString();
      return response({authorizeUrl:auth.href,state});
    }
    if(action==='shopify_oauth_exchange'){
      const config=await shopifyOAuthConfig(admin,caller.data_owner_id);
      if(!config.ready)throw new Error('La app de Shopify no está configurada.');
      const params=new URLSearchParams(clean(body.query));
      if(!await verifyShopifyCallback(params,config.clientSecret))throw new Error('La respuesta de Shopify no tiene una firma válida.');
      const domain=shopifyDomain(params.get('shop'));
      const stateHash=await shopifyHash(params.get('state')||'');
      const found=await admin.from('integration_accounts').select('*').eq('owner_id',caller.data_owner_id).eq('provider','shopify').eq('external_account_id',domain).maybeSingle();
      if(found.error)throw found.error;
      const account=found.data;
      if(!account)throw new Error('No se encontró la autorización pendiente.');
      const current=await readVault(admin,account.secret_id),pending=current.oauthPending;
      if(!pending||pending.stateHash!==stateHash||pending.userId!==caller.user_id||pending.expiresAt<Date.now())throw new Error('La autorización ha caducado o ya se ha utilizado. Vuelve a conectar Shopify.');
      if(!params.get('code'))throw new Error('Shopify no concedió la autorización.');
      const nextConfig={...account.config};delete nextConfig.oauthStateHash;
      const claimed=await admin.from('integration_accounts').update({config:nextConfig}).eq('id',account.id).eq('owner_id',caller.data_owner_id).eq('shopify_credential_version',account.shopify_credential_version).eq('enabled',true).neq('status','disabled').eq('config->>oauthStateHash',stateHash).select('id').maybeSingle();
      if(claimed.error)throw claimed.error;
      if(!claimed.data)throw new Error('Esta autorización ya se ha utilizado.');
      const token=await shopifyTokenRequest(domain,new URLSearchParams({client_id:config.clientId,client_secret:config.clientSecret,code:params.get('code')!,expiring:'1'}));
      const stored=shopifyTokenCredentials({shopDomain:domain,authMode:'oauth',clientId:config.clientId},token);
      await commitShopifyAuthorization(admin,account,pending,stored);
      const saved=await loadAccount(admin,caller.data_owner_id,account.id);
      const defaults=await admin.from('integration_accounts').select('id').eq('owner_id',caller.data_owner_id).eq('provider','shopify').eq('is_default',true).neq('status','disabled');
      if(defaults.error)throw defaults.error;
      if(!defaults.data?.length)await makeDefault(admin,caller.data_owner_id,'shopify',saved.id);
      await testAccount(admin,caller.data_owner_id,saved);
      return response({account:publicAccount(await loadAccount(admin,caller.data_owner_id,saved.id))});
    }

    if(action.startsWith('gmail_')){
      await requireWorkspaceEntitlement(admin,caller.data_owner_id,'integration.gmail','Tu plan no incluye la integración con Gmail.');
      if(action==='gmail_list')return response({accounts:(await listAccounts(admin,caller.data_owner_id)).filter((account:any)=>account.provider==='gmail')});
      if(action==='gmail_config'){
        const config=gmailServerConfig();
        return response({persistent:config.persistent,...(config.persistent?{clientId:config.clientId}:{})});
      }
      if(action==='gmail_consolidate'){
        const account=await loadAccount(admin,caller.data_owner_id,clean(body.id));
        return response({account:publicAccount(await consolidateLegacyGmail(admin,caller.data_owner_id,account))});
      }
      if(action==='gmail_token'){
        const account=await loadAccount(admin,caller.data_owner_id,clean(body.id));
        if(account.provider!=='gmail'||!account.enabled||account.status==='disabled')throw new Error('La cuenta de Gmail está desactivada o no es válida.');
        return response({connection:await renewGmail(admin,account,true)});
      }
      if(action==='gmail_exchange'){
        const config=gmailServerConfig();
        if(!config.persistent)throw new Error('La conexión persistente de Google no está habilitada.');
        const origin=validateGmailOrigin(req.headers.get('Origin'),req.headers.get('X-Requested-With'),config.allowedOrigins);
        const code=clean(body.code);
        if(!code)throw new Error('Google no devolvió un código de autorización.');
        const token=await gmailTokenRequest(new URLSearchParams({grant_type:'authorization_code',code,client_id:config.clientId,client_secret:config.clientSecret,redirect_uri:origin}));
        const email=await gmailProfileEmail(token.access_token);
        if(body.expectedEmail&&clean(body.expectedEmail).toLowerCase()!==email)throw new Error(`Selecciona ${clean(body.expectedEmail)} en Google para renovar esta cuenta.`);
        const existing=await admin.from('integration_accounts').select('*').eq('owner_id',caller.data_owner_id).eq('provider','gmail').eq('external_account_id',email).maybeSingle();
        if(existing.error)throw existing.error;
        const previous=existing.data?.secret_id?await readVault(admin,existing.data.secret_id):{};
        const refreshToken=token.refresh_token||(previous.clientId===config.clientId?previous.refreshToken:'');
        if(!refreshToken)throw new Error('Google no concedió acceso persistente. Revoca el permiso de Zenvia en Google y vuelve a conectar la cuenta.');
        const connection=gmailConnectionFromToken(token,email);
        let account=existing.data;
        if(!account){
          const count=await admin.from('integration_accounts').select('id',{count:'exact',head:true}).eq('owner_id',caller.data_owner_id).eq('provider','gmail').eq('enabled',true);
          if(count.error)throw count.error;
          const inserted=await admin.from('integration_accounts').insert({owner_id:caller.data_owner_id,provider:'gmail',display_name:email,external_account_id:email,is_default:!count.count,credential_source:'vault',config:body.config||{}}).select('*').single();
          if(inserted.error)throw inserted.error;
          account=inserted.data;
        }
        const secretId=await writeVault(admin,account.id,'gmail',{clientId:config.clientId,refreshToken,...connection},account.secret_id);
        const now=new Date().toISOString();
        const restoredConfig={...account.config,...body.config};
        delete restoredConfig.archivedAt;
        const saved=await admin.from('integration_accounts').update({secret_id:secretId,credential_source:'vault',enabled:true,status:'connected',last_error:null,last_success_at:now,updated_at:now,config:restoredConfig}).eq('id',account.id).eq('owner_id',caller.data_owner_id).select('*').single();
        if(saved.error)throw saved.error;
        return response({account:publicAccount(await consolidateLegacyGmail(admin,caller.data_owner_id,saved.data)),connection});
      }
      throw new Error('Acción de Gmail no válida.');
    }

    if(action==='list')return response({accounts:await listAccounts(admin,caller.data_owner_id)});

    if(action==='discover_shopify'){
      const parentId=clean(body?.parentAccountId);
      const parent=await loadAccount(admin,caller.data_owner_id,parentId);
      if(parent.provider!=='sendcloud')throw new Error('Selecciona una cuenta de Sendcloud.');
      const integrations=await sendcloudIntegrations(admin,parent);
      return response({shops:integrations.filter((x:any)=>x.channel==='shopify')});
    }

    if(action==='create'){
      const provider=clean(body?.provider) as Provider;
      if(!PROVIDERS.has(provider))throw new Error('Proveedor de integración no válido.');

      const providerEntitlement:Record<string,{key:string;message:string}>={
        amazon:{key:'integration.amazon',message:'Tu plan no incluye la integración con Amazon.'},
        shopify:{key:'integration.shopify',message:'Tu plan no incluye la integración con Shopify.'},
        sendcloud:{key:'integration.sendcloud',message:'Tu plan no incluye integraciones logísticas.'},
        envia:{key:'integration.envia',message:'Tu plan no incluye la integración con Envia.com.'},
        mrw:{key:'integration.sendcloud',message:'Tu plan no incluye integraciones logísticas.'},
        gmail:{key:'integration.gmail',message:'Tu plan no incluye la integración con Gmail.'},
      };
      const configuredEntitlement=providerEntitlement[provider];
      if(configuredEntitlement){
        await requireWorkspaceEntitlement(admin,caller.data_owner_id,configuredEntitlement.key,configuredEntitlement.message);
      }
      if(provider==='amazon'){
        const {count,error:amazonCountError}=await admin.from('integration_accounts')
          .select('id',{count:'exact',head:true})
          .eq('owner_id',caller.data_owner_id)
          .eq('provider','amazon')
          .neq('status','disabled');
        if(amazonCountError)throw amazonCountError;
        await enforceWorkspaceLimit(
          admin,
          caller.data_owner_id,
          'amazon_accounts',
          Number(count||0),
          'Tu plan no permite conectar cuentas de Amazon.',
          limit=>`Has alcanzado el límite de ${limit} cuentas Amazon de tu plan.`,
        );
      }
      let displayName=clean(body?.displayName);
      let externalAccountId=clean(body?.externalAccountId)||null;
      let credentialSource='vault';
      let parentAccountId=clean(body?.parentAccountId)||null;
      let config=(body?.config&&typeof body.config==='object'&&!Array.isArray(body.config))?body.config:{};
      const credentials=(body?.credentials&&typeof body.credentials==='object'&&!Array.isArray(body.credentials))?body.credentials:{};
      if(provider==='amazon'){
        externalAccountId=clean((credentials as any).sellerId||(credentials as any).seller_id||externalAccountId);
        if(!externalAccountId)throw new Error('Indica el Seller ID de Amazon.');
        if(!clean((credentials as any).refreshToken||(credentials as any).refresh_token))throw new Error('Indica el refresh token de Amazon.');
        displayName=displayName||`Amazon · ${externalAccountId}`;
      }else if(provider==='sendcloud'){
        if(!clean((credentials as any).publicKey||(credentials as any).public_key)||!clean((credentials as any).secretKey||(credentials as any).secret_key))throw new Error('Indica las claves Public y Secret de Sendcloud.');
        externalAccountId=externalAccountId||`sendcloud-${crypto.randomUUID()}`;
        displayName=displayName||'Sendcloud';
      }else if(provider==='envia'){
        if(!clean((credentials as any).token||(credentials as any).apiToken||(credentials as any).api_token))throw new Error('Indica el token API de Envia.com.');
        externalAccountId=externalAccountId||`envia-${crypto.randomUUID()}`;
        displayName=displayName||'Envia.com';
        config={...config,environment:config?.environment==='production'?'production':'sandbox',shippingEnabled:true};
      }else if(provider==='mrw'){
        if(!clean((credentials as any).franchiseCode)||!clean((credentials as any).subscriberCode)||!clean((credentials as any).username)||!clean((credentials as any).password))throw new Error('Indica franquicia, abonado, usuario y contraseña de MRW.');
        externalAccountId=externalAccountId||`${clean((credentials as any).franchiseCode)}-${clean((credentials as any).subscriberCode)}`;
        displayName=displayName||'MRW';
        config={...config,environment:config?.environment==='test'?'test':'production',shippingEnabled:true,serviceCode:clean(config?.serviceCode)||'0205',serviceName:clean(config?.serviceName)||'MRW Urgent 19:00'};
      }else if(provider==='shopify'){
        const shopDomain=normalizeShopifyDomain((credentials as any).shopDomain||(credentials as any).shop_domain||externalAccountId);
        const accessToken=clean((credentials as any).accessToken||(credentials as any).access_token);
        if(!shopDomain||!accessToken)throw new Error('Indica el dominio myshopify.com y el access token de Shopify.');
        externalAccountId=shopDomain;
        parentAccountId=null;
        displayName=displayName||shopDomain.replace(/\.myshopify\.com$/i,'');
        config={...config,shopDomain,apiVersion:clean(config?.apiVersion)||'2026-07',syncOrders:config?.syncOrders!==false};
        credentialSource='vault';
      }else{
        if(!externalAccountId)throw new Error('Indica el correo de la cuenta de Gmail.');
        displayName=displayName||externalAccountId;credentialSource='session';
      }
      const existing=await admin.from('integration_accounts').select('*').eq('owner_id',caller.data_owner_id).eq('provider',provider).eq('external_account_id',externalAccountId).maybeSingle();
      if(existing.error)throw existing.error;
      if(existing.data&&!existing.data.config?.archivedAt)throw new Error('Esta cuenta ya está añadida.');

      const count=await admin.from('integration_accounts').select('id',{count:'exact',head:true}).eq('owner_id',caller.data_owner_id).eq('provider',provider).neq('status','disabled');
      if(count.error)throw count.error;
      const isDefault=Number(count.count||0)===0;
      // Reconnect an archived identity using its original ID: this preserves
      // historical foreign keys and avoids the provider/external-ID uniqueness constraint.
      const payload={
        display_name:displayName,external_account_id:externalAccountId,
        status:'pending',enabled:true,is_default:isDefault,credential_source:credentialSource,
        parent_account_id:parentAccountId,config:{...config},
        last_error:null,updated_at:new Date().toISOString(),
      };
      const result=existing.data?.config?.archivedAt
        ?await admin.from('integration_accounts').update(payload)
          .eq('id',existing.data.id).eq('owner_id',caller.data_owner_id).select('*').single()
        :await admin.from('integration_accounts').insert({
          owner_id:caller.data_owner_id,provider,...payload,
        }).select('*').single();
      if(result.error)throw result.error;
      let account=result.data;
      if(provider==='amazon'||provider==='sendcloud'||provider==='envia'||provider==='mrw'||provider==='shopify'){
        const secretId=await writeVault(admin,account.id,provider,credentials,account.secret_id||null);
        const saved=await admin.from('integration_accounts').update({secret_id:secretId,updated_at:new Date().toISOString()})
          .eq('id',account.id).eq('owner_id',caller.data_owner_id).select('*').single();
        if(saved.error)throw saved.error;account=saved.data;
      }
      if(body?.test!==false)await testAccount(admin,caller.data_owner_id,account);
      return response({account:publicAccount(await loadAccount(admin,caller.data_owner_id,account.id))});
    }

    const id=clean(body?.id);
    if(!id)throw new Error('Falta la cuenta de integración.');
    const account=await loadAccount(admin,caller.data_owner_id,id);

    if(action==='test'){
      const result=await testAccount(admin,caller.data_owner_id,account);
      return response({...result,account:publicAccount(await loadAccount(admin,caller.data_owner_id,id))});
    }
    if(action==='set_default'){
      await makeDefault(admin,caller.data_owner_id,account.provider,id);
      return response({accounts:await listAccounts(admin,caller.data_owner_id)});
    }
    if(action==='update'){
      if(body?.enabled===true&&account.enabled===false){
        const providerEntitlement:Record<string,{key:string;message:string}>={
          amazon:{key:'integration.amazon',message:'Tu plan no incluye la integración con Amazon.'},
        shopify:{key:'integration.shopify',message:'Tu plan no incluye la integración con Shopify.'},
          sendcloud:{key:'integration.sendcloud',message:'Tu plan no incluye integraciones logísticas.'},
          envia:{key:'integration.envia',message:'Tu plan no incluye la integración con Envia.com.'},
          gmail:{key:'integration.gmail',message:'Tu plan no incluye la integración con Gmail.'},
        };
        const configuredEntitlement=providerEntitlement[account.provider];
        if(configuredEntitlement){
          await requireWorkspaceEntitlement(admin,caller.data_owner_id,configuredEntitlement.key,configuredEntitlement.message);
        }
        if(account.provider==='amazon'){
          const {count,error:amazonCountError}=await admin.from('integration_accounts')
            .select('id',{count:'exact',head:true})
            .eq('owner_id',caller.data_owner_id)
            .eq('provider','amazon')
            .eq('enabled',true)
            .neq('status','disabled');
          if(amazonCountError)throw amazonCountError;
          await enforceWorkspaceLimit(
            admin,
            caller.data_owner_id,
            'amazon_accounts',
            Number(count||0),
            'Tu plan no permite conectar cuentas de Amazon.',
            limit=>`Has alcanzado el límite de ${limit} cuentas Amazon de tu plan.`,
          );
        }
      }
      const patch:any={updated_at:new Date().toISOString()};
      if(typeof body?.displayName==='string'&&clean(body.displayName))patch.display_name=clean(body.displayName);
      if(typeof body?.enabled==='boolean')patch.enabled=body.enabled;
      if(body?.config&&typeof body.config==='object'&&!Array.isArray(body.config))patch.config={...(account.config||{}),...body.config};
      const credentials=(body?.credentials&&typeof body.credentials==='object'&&!Array.isArray(body.credentials))?body.credentials:null;
      if(credentials&&(account.provider==='amazon'||account.provider==='sendcloud'||account.provider==='envia'||account.provider==='mrw'||account.provider==='shopify')){
        const existing=account.secret_id?await readVault(admin,account.secret_id):{};
        const merged=account.provider==='shopify'&&clean((credentials as any).accessToken)
          ?shopifyLegacyCredentials((credentials as any).shopDomain||account.external_account_id,(credentials as any).accessToken)
          :{...existing,...Object.fromEntries(Object.entries(credentials).filter(([,v])=>clean(v)))};
        patch.secret_id=await writeVault(admin,account.id,account.provider,merged,account.secret_id);
        patch.status='pending';patch.last_error=null;
        if(account.provider==='shopify'){
          const shopDomain=normalizeShopifyDomain((merged as any).shopDomain||(merged as any).shop_domain||body?.config?.shopDomain||account.external_account_id);
          const accessToken=clean((merged as any).accessToken||(merged as any).access_token);
          if(!shopDomain||!accessToken)throw new Error('Indica el dominio myshopify.com y el access token de Shopify.');
          patch.external_account_id=shopDomain;
          patch.parent_account_id=null;
          patch.credential_source='vault';
          patch.config={...(account.config||{}),...(body?.config||{}),authMode:(merged as any).authMode||'token',shopDomain,apiVersion:clean(body?.config?.apiVersion||account.config?.apiVersion)||'2026-07',syncOrders:body?.config?.syncOrders!==false};
        }
      }
      const saved=await admin.from('integration_accounts').update(patch).eq('id',id).eq('owner_id',caller.data_owner_id).select('*').single();
      if(saved.error)throw saved.error;
      if(body?.isDefault===true)await makeDefault(admin,caller.data_owner_id,account.provider,id);
      return response({account:publicAccount(await loadAccount(admin,caller.data_owner_id,id))});
    }
    if(action==='delete'){
      // Deletion is an archive, not a database CASCADE. Imported orders,
      // receipts and Gmail documents must keep their original account links.
      const {data:children,error:childrenError}=await admin.from('integration_accounts')
        .select('id').eq('owner_id',caller.data_owner_id).eq('parent_account_id',account.id)
        .eq('enabled',true).neq('status','disabled').limit(1);
      if(childrenError)throw childrenError;
      if(children?.length)throw new Error('Esta integración tiene cuentas vinculadas activas. Elimínalas o desconéctalas primero.');

      const now=new Date().toISOString();
      const wasDefault=Boolean(account.is_default);
      // Disabling first is fail-closed: a concurrent sync cannot reuse the account.
      const archived=await admin.from('integration_accounts').update({
        enabled:false,status:'disabled',is_default:false,last_error:null,
        config:{...(account.config||{}),archivedAt:now},updated_at:now,
      }).eq('id',id).eq('owner_id',caller.data_owner_id).select('id').single();
      if(archived.error)throw archived.error;

      let gmailRefreshToken='';
      if(account.provider==='gmail'&&account.secret_id){
        try{gmailRefreshToken=clean((await readVault(admin,account.secret_id)).refreshToken);}
        catch{/* The credentials will still be locally revoked. */}
      }
      // Make previously issued access tokens inaccessible without erasing
      // historical business rows. Reconnect will always require new credentials.
      if(account.secret_id){
        await writeVault(admin,account.id,account.provider,
          {revoked:true,revokedAt:now},account.secret_id);
      }
      if(gmailRefreshToken){
        try{await fetch('https://oauth2.googleapis.com/revoke',{
          method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},
          body:new URLSearchParams({token:gmailRefreshToken}),
          signal:AbortSignal.timeout(8000),
        });}catch{/* Local credentials are already unusable. */}
      }
      if(account.provider==='amazon'&&account.linked_resource_id){
        const linked=await admin.from('amazon_accounts').update({status:'disabled',updated_at:now})
          .eq('id',account.linked_resource_id).eq('owner_id',caller.data_owner_id);
        if(linked.error)throw linked.error;
      }
      if(wasDefault){
        const replacement=await admin.from('integration_accounts').select('id')
          .eq('owner_id',caller.data_owner_id).eq('provider',account.provider)
          .eq('enabled',true).neq('status','disabled')
          .order('updated_at',{ascending:false}).limit(1).maybeSingle();
        if(replacement.error)throw replacement.error;
        if(replacement.data)await makeDefault(admin,caller.data_owner_id,account.provider,replacement.data.id);
      }
      return response({accounts:await listAccounts(admin,caller.data_owner_id)});
    }
    if(action==='disconnect'){
      if(account.provider==='gmail'&&account.secret_id){
        const stored=await readVault(admin,account.secret_id);
        if(stored.refreshToken){try{await fetch('https://oauth2.googleapis.com/revoke',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({token:stored.refreshToken})});}catch{/* Disable locally even if Google is unavailable. */}}
      }
      if(account.secret_id&&account.provider!=='shopify'){
        await writeVault(admin,account.id,account.provider,{revoked:true,revokedAt:new Date().toISOString()},account.secret_id);
      }
      const disabled=await admin.from('integration_accounts').update({
        enabled:false,status:'disabled',is_default:false,last_error:null,updated_at:new Date().toISOString(),
      }).eq('id',id).eq('owner_id',caller.data_owner_id);
      if(disabled.error)throw disabled.error;
      if(account.provider==='shopify'&&account.secret_id)await writeVault(admin,account.id,'shopify',{revoked:true,revokedAt:new Date().toISOString()},account.secret_id);
      if(account.provider==='amazon'&&account.linked_resource_id){
        await admin.from('amazon_accounts').update({status:'disabled',updated_at:new Date().toISOString()})
          .eq('id',account.linked_resource_id).eq('owner_id',caller.data_owner_id);
      }
      const replacement=await admin.from('integration_accounts').select('id').eq('owner_id',caller.data_owner_id)
        .eq('provider',account.provider).neq('status','disabled').order('updated_at',{ascending:false}).limit(1).maybeSingle();
      if(replacement.data)await makeDefault(admin,caller.data_owner_id,account.provider,replacement.data.id);
      return response({accounts:await listAccounts(admin,caller.data_owner_id)});
    }
    throw new Error('Acción no válida.');
  }catch(error){
    const message=sanitize(error instanceof Error?error.message:error)||'Error interno.';
    const status=/Sesión no válida/.test(message)?401:/administrador|acceso desactivado/.test(message)?403:/no encontrada/.test(message)?404:400;
    return response({error:message},status);
  }
});

export type AmazonSpApiCredentials={
  clientId:string;
  clientSecret:string;
  refreshToken:string;
  sellerId:string;
};

function clean(value:unknown){return String(value??'').trim();}
function required(value:unknown,name:string){
  const text=clean(value);
  if(!text)throw new Error(`Falta ${name} en la configuración de Amazon SP-API.`);
  return text;
}
function parseEnv(){
  const raw=clean(Deno.env.get('AMAZON_SPAPI_CREDENTIALS'));
  if(!raw)return {} as any;
  try{return JSON.parse(raw)}catch{throw new Error('AMAZON_SPAPI_CREDENTIALS no contiene JSON válido.');}
}
function normalize(stored:any,env:any,fallbackSellerId=''):AmazonSpApiCredentials{
  const refreshToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!refreshToken)throw new Error('cuenta Amazon sin credenciales');
  return {
    // SP-API/LWA app credentials can be shared by every tenant using the same
    // registered application. Seller-specific credentials cannot.
    clientId:required(stored?.clientId||stored?.client_id||env?.clientId||env?.client_id,'client_id'),
    clientSecret:required(stored?.clientSecret||stored?.client_secret||env?.clientSecret||env?.client_secret,'client_secret'),
    refreshToken:refreshToken,
    sellerId:required(stored?.sellerId||stored?.seller_id||fallbackSellerId,'seller_id'),
  };
}

export function readAmazonSpApiCredentials():AmazonSpApiCredentials{
  throw new Error('cuenta Amazon sin credenciales');
}

async function readIntegrationSecret(admin:any,integrationAccountId:string,ownerId?:string|null){
  let query=admin.from('integration_accounts')
    .select('id,owner_id,external_account_id,secret_id,credential_source,status,enabled')
    .eq('id',integrationAccountId).eq('provider','amazon');
  if(ownerId)query=query.eq('owner_id',ownerId);
  const {data:integration,error}=await query.maybeSingle();
  if(error)throw error;
  if(!integration)throw new Error('La cuenta de integración de Amazon no existe.');
  if(integration.status==='disabled'||integration.enabled===false)throw new Error('La cuenta de Amazon está deshabilitada.');
  let stored:any={};
  if(integration.secret_id){
    const {data:secret,error:secretError}=await admin.rpc('integration_read_secret',{p_secret_id:integration.secret_id});
    if(secretError)throw secretError;
    try{stored=JSON.parse(String(secret||'{}'))}catch{throw new Error('Las credenciales cifradas de Amazon no tienen un formato válido.');}
  }
  return {integration,stored};
}

export async function loadAmazonSpApiCredentials(
  admin:any,
  options:{amazonAccountId?:string|null;integrationAccountId?:string|null;ownerId?:string|null}={},
):Promise<AmazonSpApiCredentials>{
  const env=parseEnv();
  const ownerId=clean(options.ownerId);
  let integrationAccountId=clean(options.integrationAccountId);
  let fallbackSellerId='';
  let accountOwnerId=ownerId;

  if(options.amazonAccountId){
    let accountQuery=admin.from('amazon_accounts')
      .select('seller_id,integration_account_id,owner_id')
      .eq('id',options.amazonAccountId);
    if(ownerId)accountQuery=accountQuery.eq('owner_id',ownerId);
    const {data:account,error}=await accountQuery.maybeSingle();
    if(error)throw error;
    if(!account)throw new Error('La cuenta Amazon asociada al trabajo ya no existe.');
    if(integrationAccountId&&integrationAccountId!==clean(account.integration_account_id)){
      throw new Error('La cuenta de integración no corresponde al trabajo de Amazon.');
    }
    accountOwnerId=clean(account.owner_id);
    fallbackSellerId=clean(account.seller_id);
    integrationAccountId=integrationAccountId||clean(account.integration_account_id);
  }

  if(!integrationAccountId){
    throw new Error('Amazon SP-API no está configurado para este workspace.');
  }

  const {integration,stored}=await readIntegrationSecret(admin,integrationAccountId,accountOwnerId||null);
  const ownToken=clean(stored?.refreshToken)||clean(stored?.refresh_token);
  if(!ownToken){
    // This allowlist contains integration_accounts.id, never a seller ID or a
    // caller-supplied workspace. The row above has already been owner-checked.
    const allowedId=clean(Deno.env.get('AMAZON_LEGACY_FALLBACK_ACCOUNT_ID'));
    const legacyToken=clean(env?.refreshToken)||clean(env?.refresh_token);
    if(!allowedId||clean(integration.id)!==allowedId||!legacyToken){
      throw new Error('cuenta Amazon sin credenciales');
    }
    const credentials=normalize({refreshToken:legacyToken},env,clean(integration.external_account_id)||fallbackSellerId);
    console.warn('amazon_legacy_fallback_used',{integration_account_id:integration.id,owner_id:integration.owner_id});
    return credentials;
  }
  return normalize(stored,env,clean(integration.external_account_id)||fallbackSellerId);
}

export function shopifyError(error:unknown,fallback='No se pudo completar la conexión con Shopify.'):string{
  if(typeof error==='string'&&error.trim()&&error!=='[object Object]')return error.trim();
  if(error&&typeof error==='object'){
    const value=error as Record<string,unknown>;
    for(const key of ['message','error','error_description','details']){
      if(value[key]&&value[key]!==error){const detail=shopifyError(value[key],'');if(detail)return detail;}
    }
  }
  return fallback;
}

export function shopifyDomain(value:unknown){
  const domain=String(value??'').trim().toLowerCase().replace(/^https:\/\//,'').replace(/\/$/,'');
  if(!/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(domain))throw new Error('Indica el dominio permanente de Shopify: tienda.myshopify.com, sin rutas.');
  return domain;
}

export function shopifyLegacyCredentials(domain:unknown,accessToken:unknown){
  const token=String(accessToken??'').trim();
  if(!token)throw new Error('Indica el access token de la app antigua.');
  return {shopDomain:shopifyDomain(domain),accessToken:token,authMode:'token'};
}

export function shopifyApplicationCredentials(environment:any,configured:any){
  const candidate=environment?.clientId&&environment?.clientSecret?environment:configured;
  const clientId=String(candidate?.clientId||'').trim(),clientSecret=String(candidate?.clientSecret||'').trim();
  return {clientId,clientSecret,ready:Boolean(clientId&&clientSecret)};
}

export async function shopifyStoredApplicationCredentials(admin:any,ownerId:string){
  const environment={clientId:Deno.env.get('SHOPIFY_CLIENT_ID')||'',clientSecret:Deno.env.get('SHOPIFY_CLIENT_SECRET')||''};
  let configured={};
  if(!environment.clientId||!environment.clientSecret){
    const result=await admin.rpc('integration_read_named_secret',{p_name:`shopify-app:${ownerId}`});
    if(result.error)throw result.error;
    try{configured=JSON.parse(result.data||'{}')}catch{}
  }
  return shopifyApplicationCredentials(environment,configured);
}

export async function shopifyHash(value:string){
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))).map(v=>v.toString(16).padStart(2,'0')).join('');
}

export async function verifyShopifyCallback(params:URLSearchParams,secret:string){
  const keys=[...params.keys()];
  if(new Set(keys).size!==keys.length)return false;
  const supplied=params.get('hmac')||'';
  if(!/^[a-f0-9]{64}$/.test(supplied))return false;
  const message=[...params.entries()].filter(([key])=>key!=='hmac').sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>`${k}=${v}`).join('&');
  const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),{name:'HMAC',hash:'SHA-256'},false,['verify']);
  const signature=new Uint8Array(supplied.match(/../g)!.map(v=>parseInt(v,16)));
  return crypto.subtle.verify('HMAC',key,signature,new TextEncoder().encode(message));
}

export async function shopifyTokenRequest(domain:string,body:URLSearchParams){
  const res=await fetch(`https://${shopifyDomain(domain)}/admin/oauth/access_token`,{
    method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',Accept:'application/json'},body,
    redirect:'error',signal:AbortSignal.timeout(20000),
  });
  const token=await res.json().catch(()=>({}));
  if(!res.ok||token.error)throw new Error(token.error==='invalid_client'?'Shopify no acepta el ID o secreto de la app. Comprueba sus credenciales.':token.error==='shop_not_permitted'?'La app y la tienda deben pertenecer a la misma organización Shopify. Para tiendas de clientes utiliza Autorizar con Shopify.':token.error==='invalid_grant'?'Shopify ha caducado o revocado la autorización. Vuelve a conectar la tienda.':`Shopify (${res.status}): no se pudo obtener la autorización. Comprueba que la app esté instalada y tenga permiso read_orders.`);
  return token;
}

export function shopifyTokenCredentials(stored:any,token:any,now=Date.now()){
  if(!token?.access_token)throw new Error('Shopify no devolvió un access token.');
  const grantedScopes=new Set(String(token.scope||'').split(/[\s,]+/).filter(Boolean));
  if(!grantedScopes.has('read_orders')&&!grantedScopes.has('write_orders'))throw new Error('La app necesita permiso read_orders o write_orders. Añádelo en Shopify y vuelve a autorizar.');
  if(token.expires_in!=null&&(!Number.isFinite(Number(token.expires_in))||Number(token.expires_in)<=0))throw new Error('Shopify devolvió una caducidad no válida.');
  return {...stored,accessToken:String(token.access_token),scope:String(token.scope),expiresAt:token.expires_in?now+Number(token.expires_in)*1000:null,...(token.refresh_token?{refreshToken:String(token.refresh_token)}:{})};
}

export async function resolveShopifyCredentials(stored:any,config:any,request=shopifyTokenRequest,persist?: (stored:any)=>Promise<unknown>){
  const domain=shopifyDomain(stored.shopDomain||stored.shop_domain||config.shopDomain);
  let token=String(stored.accessToken||stored.access_token||'').trim();
  if(!token||(stored.expiresAt&&Number(stored.expiresAt)<=Date.now()+300000)){
    const clientId=stored.clientId||Deno.env.get('SHOPIFY_CLIENT_ID');
    const clientSecret=stored.clientSecret||Deno.env.get('SHOPIFY_CLIENT_SECRET');
    if(!clientId||!clientSecret)throw new Error('Renueva la conexión con Shopify desde Integraciones.');
    const fields:Record<string,string>={client_id:clientId,client_secret:clientSecret};
    if(stored.authMode==='client_credentials')fields.grant_type='client_credentials';
    else if(stored.refreshToken){fields.grant_type='refresh_token';fields.refresh_token=stored.refreshToken;}
    else throw new Error('Renueva la autorización de Shopify desde Integraciones.');
    const renewed=shopifyTokenCredentials(stored,await request(domain,new URLSearchParams(fields)));
    if(persist)await persist(renewed);
    token=renewed.accessToken;
  }
  return {shopDomain:domain,accessToken:token,apiVersion:String(config.apiVersion||'2026-07')};
}

export async function shopifyAccountCredentials(admin:any,account:any,appCredentials?:{clientId:string;clientSecret:string}){
  async function read(){
    const result=await admin.from('integration_accounts').select('*').eq('id',account.id).eq('owner_id',account.owner_id).maybeSingle();
    if(result.error)throw result.error;
    if(!result.data?.enabled||result.data.status==='disabled')throw new Error('La cuenta Shopify está desconectada.');
    const secret=await admin.rpc('integration_read_secret',{p_secret_id:result.data.secret_id});
    if(secret.error)throw secret.error;
    return {row:result.data,stored:JSON.parse(secret.data||'{}')};
  }
  let current=await read();
  if(current.stored.accessToken&&(!current.stored.expiresAt||current.stored.expiresAt>Date.now()+300000))return resolveShopifyCredentials(current.stored,current.row.config||{});
  const lease=crypto.randomUUID();
  let claimed=false;
  for(let attempt=0;attempt<125;attempt++){
    const result=await admin.rpc('integration_shopify_claim_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease});
    if(result.error)throw result.error;
    if(result.data){claimed=true;break;}
    await new Promise(resolve=>setTimeout(resolve,200));
    current=await read();
    if(current.stored.accessToken&&(!current.stored.expiresAt||current.stored.expiresAt>Date.now()+300000))return resolveShopifyCredentials(current.stored,current.row.config||{});
  }
  if(!claimed)throw new Error('Shopify está renovando la autorización. Vuelve a intentarlo en unos segundos.');
  try{
    current=await read();
    if(current.stored.authMode==='oauth'&&appCredentials&&current.stored.clientId!==appCredentials.clientId)throw new Error('La app Shopify cambió. Vuelve a autorizar esta tienda.');
    const storedForRenewal=current.stored.authMode==='oauth'&&appCredentials?{...current.stored,clientSecret:appCredentials.clientSecret}:current.stored;
    return await resolveShopifyCredentials(storedForRenewal,current.row.config||{},shopifyTokenRequest,async stored=>{
      if(current.stored.authMode==='oauth')delete stored.clientSecret;
      const result=await admin.rpc('integration_shopify_commit_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease,p_version:current.row.shopify_credential_version,p_secret:JSON.stringify(stored)});
      if(result.error)throw result.error;
      if(!result.data)throw new Error('La conexión de Shopify cambió durante la renovación. Vuelve a intentarlo.');
    });
  }finally{
    await admin.rpc('integration_shopify_release_refresh',{p_account_id:account.id,p_owner_id:account.owner_id,p_lease:lease});
  }
}

export async function commitShopifyAuthorization(admin:any,account:any,pending:any,stored:any){
  const config={...(account.config||{}),shopDomain:stored.shopDomain,authMode:'oauth',syncOrders:pending.syncOrders!==false,apiVersion:'2026-07'};
  delete config.oauthStateHash;
  const result=await admin.rpc('integration_shopify_complete_oauth',{p_account_id:account.id,p_owner_id:account.owner_id,p_version:account.shopify_credential_version,p_secret:JSON.stringify(stored),p_display_name:pending.displayName||account.display_name,p_config:config});
  if(result.error)throw result.error;
  if(!result.data)throw new Error('La conexión de Shopify cambió mientras autorizabas. Vuelve a conectar la tienda.');
}

export async function verifyShopifyInstallLaunch(params:URLSearchParams,secret:string,now=Date.now()){
  if(params.has('code')||params.has('state')||params.has('error'))throw new Error('Retorno de instalación Shopify no válido.');
  const timestamp=Number(params.get('timestamp'));
  if(!Number.isInteger(timestamp)||timestamp<=0||Math.abs(now/1000-timestamp)>600)throw new Error('El enlace de Shopify ha caducado. Abre de nuevo la app desde Shopify.');
  if(!await verifyShopifyCallback(params,secret))throw new Error('Firma de instalación Shopify no válida.');
  return shopifyDomain(params.get('shop'));
}

export type WorkspaceEntitlement={
  configured:boolean;
  enabled:boolean;
  limit:number|null;
};

function numericLimit(raw:unknown){
  if(typeof raw==='number'&&Number.isFinite(raw))return raw;
  if(raw===null||raw===undefined||raw==='')return null;
  const parsed=Number(raw);
  return Number.isFinite(parsed)?parsed:null;
}

export async function loadWorkspaceEntitlement(admin:any,workspaceId:string,entitlementKey:string):Promise<WorkspaceEntitlement>{
  const {data:snapshot,error:snapshotError}=await admin
    .from('app_subscription_state')
    .select('status,entitlements')
    .eq('workspace_id',workspaceId)
    .maybeSingle();
  if(snapshotError)throw snapshotError;

  if(snapshot&&['active','trialing'].includes(String(snapshot.status||''))){
    const entitlements=snapshot.entitlements&&typeof snapshot.entitlements==='object'&&!Array.isArray(snapshot.entitlements)
      ?snapshot.entitlements as Record<string,unknown>
      :{};
    const raw=entitlements[entitlementKey];
    if(raw&&typeof raw==='object'&&!Array.isArray(raw)){
      const item=raw as Record<string,unknown>;
      return {
        configured:true,
        enabled:item.enabled!==false,
        limit:numericLimit(item.limit),
      };
    }
  }

  const {data:subscription,error:subscriptionError}=await admin
    .from('workspace_subscriptions')
    .select('plan_key,status')
    .eq('workspace_id',workspaceId)
    .maybeSingle();
  if(subscriptionError)throw subscriptionError;
  if(!subscription?.plan_key||!['active','trialing'].includes(String(subscription.status||''))){
    return {configured:false,enabled:true,limit:null};
  }

  const {data:entitlement,error:entitlementError}=await admin
    .from('plan_entitlements')
    .select('enabled,limit_value')
    .eq('plan_key',subscription.plan_key)
    .eq('entitlement_key',entitlementKey)
    .maybeSingle();
  if(entitlementError)throw entitlementError;
  if(!entitlement)return {configured:false,enabled:true,limit:null};

  return {
    configured:true,
    enabled:entitlement.enabled!==false,
    limit:numericLimit(entitlement.limit_value),
  };
}

export async function requireWorkspaceEntitlement(
  admin:any,
  workspaceId:string,
  entitlementKey:string,
  disabledMessage:string,
):Promise<WorkspaceEntitlement>{
  const entitlement=await loadWorkspaceEntitlement(admin,workspaceId,entitlementKey);
  if(entitlement.configured&&!entitlement.enabled)throw new Error(disabledMessage);
  return entitlement;
}

export async function enforceWorkspaceLimit(
  admin:any,
  workspaceId:string,
  entitlementKey:string,
  currentUsage:number,
  zeroMessage:string,
  reachedMessage:(limit:number)=>string,
){
  const entitlement=await loadWorkspaceEntitlement(admin,workspaceId,entitlementKey);
  if(entitlement.configured&&!entitlement.enabled)throw new Error(zeroMessage);
  if(entitlement.limit!==null&&currentUsage>=entitlement.limit){
    throw new Error(entitlement.limit===0?zeroMessage:reachedMessage(entitlement.limit));
  }
  return entitlement;
}

export function gmailAccessAllowed(caller:{role:string;permissions:string[]|null},action:string){
  return caller.role==='admin'||(['gmail_list','gmail_token'].includes(action)&&Boolean(caller.permissions?.includes('invoices')));
}

export function legacyGmailMigrationPlan(accounts:any[],target:any){
  if(target.provider!=='gmail'||!target.enabled||!String(target.external_account_id||'').includes('@'))throw new Error('Selecciona una cuenta real de Gmail.');
  const placeholders=accounts.filter(account=>account.owner_id===target.owner_id&&account.provider==='gmail'&&account.external_account_id==='legacy'&&account.credential_source==='session'&&!account.config?.migratedToAccountId);
  return {ids:placeholders.map(account=>account.id),transferDefault:placeholders.some(account=>account.is_default)};
}

export function validateGmailOrigin(origin:string|null,requestedWith:string|null,allowed:string[]){
  if(requestedWith!=='XmlHttpRequest')throw new Error('Solicitud de autorización no válida.');
  if(!origin||!allowed.includes(origin))throw new Error('El origen de la autorización no está permitido.');
  return origin;
}

export function gmailConnectionFromToken(token:any,email:string,now=Date.now()){
  if(!token?.access_token||!email||!Number.isFinite(Number(token.expires_in))||Number(token.expires_in)<=0)throw new Error('Google no devolvió una autorización válida.');
  return {email,accessToken:String(token.access_token),expiresAt:now+Number(token.expires_in)*1000};
}

export function gmailServerConfig(){
  const clientId=Deno.env.get('GOOGLE_CLIENT_ID')?.trim()||'';
  const clientSecret=Deno.env.get('GOOGLE_CLIENT_SECRET')?.trim()||'';
  const allowedOrigins=(Deno.env.get('GMAIL_ALLOWED_ORIGINS')||'https://gestion.zenviacommerce.com,https://gestionzenvia.vercel.app').split(',').map(value=>value.trim()).filter(Boolean);
  return {clientId,clientSecret,allowedOrigins,persistent:Boolean(clientId&&clientSecret)};
}

export async function gmailTokenRequest(body:URLSearchParams){
  const res=await fetch('https://oauth2.googleapis.com/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});
  const token=await res.json();
  if(!res.ok||token.error)throw new Error(token.error==='invalid_grant'?'Google ha caducado o revocado la autorización. Renueva la cuenta desde Integraciones.':'No se pudo completar la autorización de Google. Contacta con el administrador de Zenvia.');
  return token;
}

export async function gmailProfileEmail(accessToken:string){
  const res=await fetch('https://gmail.googleapis.com/gmail/v1/users/me/profile',{headers:{Authorization:`Bearer ${accessToken}`}});
  const profile=await res.json();
  if(!res.ok||!profile.emailAddress)throw new Error('Google no concedió permiso de lectura del buzón.');
  return String(profile.emailAddress).trim().toLowerCase();
}
